(function(r,f){const m=f();if(typeof module==='object')module.exports=m;else r.Model=m})(globalThis,()=>{function validate(s){if(!s||s.version!==1||!Number.isSafeInteger(s.revision)||s.revision<0||!['manual','daily','weekly'].includes(s.schedule)||!Array.isArray(s.lists)||s.lists.length>20||!Array.isArray(s.days)||s.days.length>7||typeof s.siteEnabled!=='boolean'||typeof s.siteOrigin!=='string')throw Error('Invalid protection state');const u=new URL(s.siteOrigin);if(!['http:','https:'].includes(u.protocol)||u.origin!==s.siteOrigin)throw Error('Invalid site');const ids=new Set();for(const x of s.lists){if(!/^[a-z0-9_-]{1,40}$/.test(x.id)||ids.has(x.id)||typeof x.name!=='string'||x.name.length>80||typeof x.enabled!=='boolean'||typeof x.available!=='boolean'||typeof x.version!=='string'||x.version.length>40)throw Error('Invalid list');ids.add(x.id)}const dates=new Set();for(const x of s.days){if(!/^\d{4}-\d{2}-\d{2}$/.test(x.day)||dates.has(x.day)||!Number.isSafeInteger(x.blocked)||x.blocked<0||x.blocked>1000000000)throw Error('Invalid count');dates.add(x.day)}return structuredClone(s)}function total(s){return validate(s).days.reduce((n,x)=>n+x.blocked,0)}function operation(s,type,value){s=validate(s);if(type==='list'){const x=s.lists.find(x=>x.id===value.id);if(!x?.available||typeof value.enabled!=='boolean')throw Error('Unavailable list')}else if(type==='schedule'){if(!['manual','daily','weekly'].includes(value))throw Error('Invalid schedule')}else if(type==='site'){if(typeof value!=='boolean')throw Error('Invalid site rule')}else if(!['update','reset'].includes(type))throw Error('Invalid action');return{expectedRevision:s.revision,type,value,siteOrigin:s.siteOrigin}}return{validate,total,operation}});
